from pathlib import Path
import sys,hashlib
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');s=Path(sys.argv[1]).read_text();start=s.index('// UnionFindW<T>');end=s.index('template<class Type>',start)
comments='''// UnionFindW<T>(n=0): n要素を構築、O(n+1)時間・領域、n<=INT_MAX。T{}は零、可換加法群の+/-/+=/符号反転が必要。
// Tはコピー・ムーブ可能。圧縮・結合中のTの算術と代入は非送出、符号付き整数の全途中結果は表現範囲内が前提。
// root(i)/leader(i): 代表、issame(a,b)/same(a,b): 同一成分か、size(i): 成分サイズ。償却O(α(n+1))。
// unite(a,b,w): weight(b)-weight(a)=wで未接続なら結合、戻り値なし。既接続の矛盾は無視する。
// merge(a,b,w): 同じ制約で新規結合ならtrue、既接続なら整合性によらずfalse。償却O(α(n+1))。
// constrain(a,b,w): 未接続なら結合しtrue、既接続なら整合するときtrue。==が必要、償却O(α(n+1))。
// weight(i): 根を零とした重み、diff(a,b): b-aの差。diffは接続が前提（既定の検査で未接続なら例外）。償却O(α(n+1))。
// try_diff(a,b): 接続済みなら差、未接続ならnullopt。償却O(α(n+1))。符号なし整数は型の幅の剰余演算。
// size()/empty()/component_count(): 全要素数/空か/成分数、O(1)。groups(): 頂点昇順の成分一覧、O(1+n α(n+1))償却。
// reset(n): 一時構築後に交換、O(旧n+n+1)上界、失敗時は元を保持。clear(): 空へ戻し容量保持、O(旧n+1)上界、noexcept。
// swap(other)/swap(a,b): 内容交換、O(1)、noexcept。コピーはO(n+1)で独立、コピー代入は強い例外保証。移動元は空。
'''
s=s[:start]+comments+s[end:]
old='return diff_w[b] - diff_w[a] == w;';fixed='return static_cast<Type>(diff_w[b] - diff_w[a]) == w;'
if old in s:s=s.replace(old,fixed)
assert s.count(fixed)==1
needle='    int root(int i)';assert s.count(needle)==1
extra='''    void reset(std::size_t n) { UnionFindW replacement(n); swap(replacement); }
    void clear() noexcept { param.clear(); diff_w.clear(); components_ = 0; }
    bool empty() const noexcept { return param.empty(); }
    friend void swap(UnionFindW& left, UnionFindW& right) noexcept { left.swap(right); }
'''
s=s.replace(needle,extra+needle);(p/'final.hpp').write_text(s);(r/'DataStructure/union_find_w.cpp').write_text(s);print('installed',hashlib.sha256(s.encode()).hexdigest())

