#endif
#include SOURCE
#include <cstdint>
#include <cstdio>
struct Destructive {
    static inline bool throw_assign=false,throw_add=false;
    std::int64_t value=0;
    Destructive()=default; explicit Destructive(std::int64_t v):value(v){}
    Destructive(const Destructive&)=default;
    Destructive& operator=(const Destructive& other) { value=other.value; if(throw_assign)throw 1; return *this; }
    Destructive& operator+=(const Destructive& other) { value+=other.value; if(throw_add)throw 2; return *this; }
    friend Destructive operator+(const Destructive&a,const Destructive&b){return Destructive(a.value+b.value);}
    friend Destructive operator-(const Destructive&a,const Destructive&b){return Destructive(a.value-b.value);}
    friend Destructive operator-(const Destructive&a){return Destructive(-a.value);}
    friend bool operator==(const Destructive&a,const Destructive&b){return a.value==b.value;}
};
int main(){
    UnionFindW<std::uint8_t> small(3);small.unite(0,1,250);small.unite(0,2,5);
    std::printf("small_unsigned expected_consistent=1 observed=%d diff=%u\n",small.constrain(1,2,11),static_cast<unsigned>(*small.try_diff(1,2)));
    UnionFindW<Destructive> linked(3);linked.unite(0,1,Destructive(3));bool threw=false;Destructive::throw_assign=true;try{linked.unite(0,2,Destructive(8));}catch(int){threw=true;}Destructive::throw_assign=false;
    std::printf("destructive_link threw=%d connected02=%d root_weight2=%jd components=%d\n",threw,linked.same(0,2),static_cast<std::intmax_t>(linked.weight(2).value),linked.component_count());
    UnionFindW<Destructive> compressed(4);compressed.unite(0,1,Destructive(3));compressed.unite(2,3,Destructive(5));compressed.unite(0,2,Destructive(7));threw=false;Destructive::throw_add=true;try{(void)compressed.root(3);}catch(int){threw=true;}Destructive::throw_add=false;
    std::printf("destructive_compression threw=%d expected_diff03=12 observed_diff03=%jd components=%d\n",threw,static_cast<std::intmax_t>(compressed.diff(0,3).value),compressed.component_count());
}
